{
  "contract": "BULLRUNNERSCLUB",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "mint"
    ],
    "justification": "Both withdraw and mint functions interact with _ethBal and team_balance, which are exposed during the risky call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "mint"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_ethBal == team_balance + inFlight",
    "stable_formula": "_ethBal == team_balance",
    "kind": "additive"
  },
  "composition": {
    "target_property": "team_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the _ethBal accounts for any in-flight ETH during the callback, maintaining the target property."
  }
}
